  /* ============================================================
     Forms / inputs (search, filters, mypage, feedback)
     ============================================================ */
  .c-form__input-text,
  .c-form__textarea,
  .c-form__select,
  input[type="text"],
  input[type="search"],
  input[type="number"],
  input[type="email"],
  input[type="password"],
  textarea,
  select {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* The open listbox is the one surface `color-scheme: dark` repaints for us —
     which turns the R18 base sheets' `* { color:#333 }` into dark-on-dark, since
     a universal selector matches <option> DIRECTLY and no colour inherited from
     the <select> can beat it. Colour only: an `option` background-color would
     paint over the browser's own selected-row highlight, the listbox's only
     "you are here" cue. */
  option {
    color: #e6edf3 !important;
  }

  /* Every control the network leaves UNstyled keeps the UA's
     `border: 2px inset|outset`, and Chromium draws that 3D bevel by
     LIGHTENING two of the four edges — measured rgb(109,124,143) on the page
     base, i.e. a bright frame that NO border-color override can reach (the
     blanket `* { border-color }` reset above sets the colour and the browser
     still derives its own shades from the style keyword). It hits the legacy
     search builder's 文字数 / 掲載日 fields, blog.syosetu.com's search box and
     the +作品検索+ box + 検索 submit on all three R18 sites. Flatten the style;
     the width is untouched, so nothing reflows. */
  input[type="text"],
  input[type="search"],
  input[type="number"],
  input[type="email"],
  input[type="password"],
  input[type="submit"],
  input[type="button"],
  textarea {
    border-style: solid !important;
  }
  /* ...but the reader's 行間 / 文字サイズ readout declares `border: none`, whose
     USED width springs from 0 to `medium` (3px) the instant a style is set —
     it would grow a frame it never had. Same for the 縦書きPDF link further
     down, which re-asserts it on its own rule. */
  input.p-adjust-layout__console-display {
    border-style: none !important;
  }

  /* The custom <select> (header scope picker, sort order, 感想絞り込み)
     paints its chevron with an inline SVG data-URI whose <path> has no
     fill — i.e. pure black. On the dark input that is ~1.05:1, an
     invisible caret. Repaint the glyph light.
     The geometry canNOT be inherited from the site: mypage ships its own
     form stylesheet where .c-form__select gets neither `appearance:none`
     nor a `background:` shorthand, so a bare `background-image` lands on
     the initial values — `repeat` tiled the 512×512 chevron across the
     whole 76×36 control and `appearance:auto` left Chromium's native
     arrow painted on top of it, burying the 作品 label. Pin every
     component. The values reproduce the site's own shorthand exactly
     where it does exist (0.85em = 11.9px at the portal/yomou/mypage 14px
     font, 10.71px at the reader's 12.6px), so only mypage changes. */
  .c-form__select {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 512 512'%3E%3Cpath fill='%23c4cdd6' d='M256,372a24.94,24.94,0,0,1-17.68-7.33L76.39,202.71a25,25,0,0,1,35.36-35.35L256,311.61,400.25,167.36a25,25,0,0,1,35.36,35.35L273.68,364.64A24.94,24.94,0,0,1,256,372Z'/%3E%3C/svg%3E") !important;
    background-repeat: no-repeat !important;
    background-position: right 5px center !important;
    background-size: 0.85em !important;
    -webkit-appearance: none !important;
    appearance: none !important;
  }

  /* Every .c-form control across the network replaces its focus outline with
     `outline: 0; box-shadow: 0 0 0 2px var(--color-form-shadow-focus)` — so
     this token is the ONLY keyboard-focus affordance on the header search,
     the search-builder fields, the filter radios/checkboxes and the feedback
     textarea. At its native 25% alpha it composites to ~1.5:1 against the
     page base, well under the 3:1 non-text floor, and the ring is invisible.
     The token is defined per site (blue on the portal, orange on yomou) and
     has no consumer other than those :focus rules, so one opaque accent
     value covers every control. */
  :root {
    --color-form-shadow-focus: rgba(88, 166, 255, 0.75) !important;
  }

  ::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }
  :-ms-input-placeholder {
    color: #8b949e !important;
  }

  /* Buttons / submit / search button */
  .c-form__input-group-button,
  button,
  input[type="submit"],
  input[type="button"],
  .btn-add,
  .btn-search,
  .js-search_conditions_btn {
    background-color: #21262d !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .c-form__input-group-button:hover,
  button:hover,
  input[type="submit"]:hover {
    background-color: #2d333b !important;
  }
  /* The chapter footer's 縦書きPDF is an <input type=button> the site renders
     as a plain link beside 作者マイページ / 誤字報告 / 情報提供. The rule above
     made it the only chip in that row. It ties `input[type="button"]` on
     specificity, so it MUST sit after it — not up with the .c-button block. */
  input.c-under-nav__pdflink {
    background-color: transparent !important;
    color: #5fb0e6 !important;
    border-color: transparent !important;
    border-style: none !important;
  }
  /* Every item in that row ends with an icon-font chevron. On the mobile sheet the
     pseudo carries its own #0033cc (~2:1 on dark) while the label beside it lifts
     to the accent blue, so the arrow reads as a near-invisible navy smudge; it is
     not a text node, so only the pseudo-text pass sees it. `inherit` pins the
     chevron to whatever its own item resolves to on either frontend — on desktop
     that is already the value it has, so nothing there changes. */
  .c-under-nav__item::after {
    color: inherit !important;
  }
  /* All four items in that row are natively the same #0033cc link, but only three are
     real <a>: on desktop they land on the footer tone via `.l-foot-contents a`, while
     the 縦書きPDF <input> can only be reached by the rule above — so one row rendered
     in two different blues. Pin the whole row to the footer tone at 0,2,1, which beats
     `.l-foot-contents a` (0,2,0) wherever this block sits in the sheet. */
  div.c-under-nav .c-under-nav__item,
  div.c-under-nav input.c-under-nav__pdflink {
    color: #9bd4ff !important;
  }

  /* Search builder legacy tables / labels / keyword tags. This older
     markup uses bare <th>/<span>/<label> at #333 inside white
