  /* Keyword-suggestion links / tabs in the legacy search builder */
  .pointer,
  .select.pointer,
  .tab_box a,
  .tab_box .pointer {
    color: #5fb0e6 !important;
  }
  /* The keyword-picker's three tabs (おすすめキーワード① / ② / リプレイ用) are
     bare <li>s carrying their own #eee fill, and #fff for the current one —
     three bright pills, and once darkened the current/inactive distinction is
     gone. They only exist after 検索ワードを選択 is clicked, and at exactly 40px
     tall they sit under the surface scanner's floor. Elevate the current tab
     and give it the amber label the rest of the network uses for "selected". */
  .tab_box li.pointer {
    background-color: #161b22 !important;
  }
  /* An unselected tab's :hover is a `background:` SHORTHAND gradient
     (#fefefe → #eee), so the background-COLOR above paints behind it and the
