  }
  /* The 検索 submit is embossed with `0 2px 0 1px rgba(255,255,255,.3)`. On the
     site's white page that stop is invisible; on ours it resolves to a solid
     rgb(91,94,97) bar hugging the bottom of the page's primary CTA — measured,
     3 CSS px tall, on both the desktop and the phone builder. Keep the emboss
     geometry, drop the light stop to a value that reads the way white does on
     white. */
  input.btn-search {
