  /* ============================================================
     jQuery UI datepicker (#ui-datepicker-div)
     The 詳細条件設定 panel's 最新掲載日 / 初回掲載日 fields open the stock
     jQuery-UI 1.12 calendar — a floating widget that does not exist in the
     DOM until a date field is clicked, so no load-time scan can reach it. It
     ships the untouched "base" theme: a solid #fff panel (.ui-widget-content),
     a #ccc header bar, #e6e6e6 day cells with #555 numerals and a cream
     .ui-state-highlight for today. Rebuild the scale on dark, and keep the
     three states distinguishable — default chip, hover chip, and the accent
     blue for the selected day, which is the widget's only selection cue.
     ============================================================ */
  .ui-widget-content {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .ui-widget-content a {
    color: #c4cdd6 !important;
  }
  .ui-widget-header {
    background: #21262d !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ui-state-default,
  .ui-widget-content .ui-state-default,
  .ui-widget-header .ui-state-default {
    background: #21262d !important;
    background-image: none !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .ui-state-hover,
  .ui-widget-content .ui-state-hover,
  .ui-state-focus,
  .ui-widget-content .ui-state-focus {
    background: #2d333b !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #3d444d !important;
  }
  .ui-state-active,
  .ui-widget-content .ui-state-active {
    background: #1f6feb !important;
    background-image: none !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  /* "Today" — the widget's warm highlight; keep it warm, not neutral, so it
     still reads as a distinct marker beside the plain day chips. */
  .ui-state-highlight,
  .ui-widget-content .ui-state-highlight {
    background: #3a2f14 !important;
    background-image: none !important;
    color: #e6c9a8 !important;
    border-color: #5a4a20 !important;
  }
  .ui-state-highlight a,
  .ui-widget-content .ui-state-highlight a {
    color: #e6c9a8 !important;
  }
  /* The <前 / 次> arrows are 16x16 cutouts of a #222 sprite sheet — a dark glyph
     on a now-dark header. The sheet is a raster, so invert it rather than
     restating a URL; the filter sits on the inner <span>, not on the <a> that
     carries the click handler. */
  .ui-datepicker .ui-icon {
    filter: invert(0.85) !important;
  }

